SELECT *
FROM shopwizard.tOrdOrderGiftRule

    AND RuleNo = #{pRuleNo}
    AND ShopCode = #{pShopCode}
    AND ChnlCode = #{pChnlCode}
    AND ChnlProdCode = #{pChnlProdCode}
    AND ChnlProdName = #{pChnlProdName}
    AND DealName = #{pDealName}
    AND GiftProdCode1 = #{pGiftProdCode1}
    AND GiftProdName1 = #{pGiftProdName1}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderGiftRule

    AND RuleNo = #{pRuleNo}
    AND ShopCode = #{pShopCode}
    AND ChnlCode = #{pChnlCode}
    AND ChnlProdCode = #{pChnlProdCode}
    AND ChnlProdName = #{pChnlProdName}
    AND DealName = #{pDealName}
    AND GiftProdCode1 = #{pGiftProdCode1}
    AND GiftProdName1 = #{pGiftProdName1}
